//! Release assurance gates for retrieval-synthesis products (P02 F25–F28).
use std::collections::BTreeSet;
use super::retrieval_support::{self, RetrievalQuery};
use bioprism_foundation::{TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.retrieval-assurance-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)] pub struct RetrievalAssuranceRequest { pub query:RetrievalQuery, pub minimum_selected:usize, pub require_signed_approval:bool, pub signed_approval:bool, pub require_federation:bool, pub federation_approved:bool, pub boundary:String }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)] pub struct RetrievalAssuranceReceipt { pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub disposition:String,pub candidate_order:Vec<String>,pub selected_order:Vec<String>,pub unresolved_order:Vec<String>,pub blocked_order:Vec<String>,pub gate_order:Vec<String>,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub replay_identity:ContentHash,pub synthesis_digest:ContentHash,pub assurance_digest:ContentHash,pub artifact:TypedResearchArtifact,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String }
#[derive(Debug,Error,Clone,PartialEq,Eq)] pub enum RetrievalAssuranceError { #[error("invalid retrieval assurance request: {0}")] Invalid(String), #[error("retrieval assurance inference failed: {0}")] Inference(String), #[error("retrieval assurance artifact failed: {0}")] Artifact(String) }
fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())} fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl RetrievalAssuranceReceipt { pub fn validate(&self)->Result<(),RetrievalAssuranceError>{ if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||self.artifact.content_type!=CONTENT_TYPE||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.candidate_order.is_empty()||self.gate_order.is_empty()||self.effect_receipts.is_empty()||![&self.replay_identity,&self.synthesis_digest,&self.assurance_digest].into_iter().all(|v|digest(v)){return Err(RetrievalAssuranceError::Invalid("assurance identity, gates, locality, digests, or effects are incomplete".into()));} for v in [&self.candidate_order,&self.selected_order,&self.unresolved_order,&self.blocked_order,&self.gate_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !ordered(v){return Err(RetrievalAssuranceError::Invalid("assurance ordering is not canonical".into()));}} let ids=self.candidate_order.iter().cloned().collect::<BTreeSet<_>>(); let parts=self.selected_order.iter().chain(self.unresolved_order.iter()).chain(self.blocked_order.iter()).cloned().collect::<BTreeSet<_>>(); if ids!=parts{return Err(RetrievalAssuranceError::Invalid("assurance states do not partition candidates".into()));} if self.effect_receipts.iter().any(|e|e!="retain:qualified-retrieval-assurance"&&e!="block:unsafe-release"){return Err(RetrievalAssuranceError::Invalid("assurance effect is outside release gate".into()));} self.artifact.validate_metadata().map_err(|e|RetrievalAssuranceError::Artifact(e.to_string())) } }
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["research program lead","benchmark curator","preclinical neuroscientist"],"behavior":format!("assure retrieval-synthesis release for {scale} under evidence and provenance gates"),"value":"prevents incomplete or unsafe retrieval synthesis from being released as qualified research evidence","input_schema":input_schema,"output_schema":"QualifiedEvidenceSet7@1","effects":["retain:qualified-retrieval-assurance","block:unsafe-release"],"permissions":["read:local-research-artifacts"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY})}
pub fn assure(request:&RetrievalAssuranceRequest,feature_id:&str,version:&str,require_approval:bool,require_federation:bool)->Result<RetrievalAssuranceReceipt,RetrievalAssuranceError>{if request.boundary!=PRECLINICAL_BOUNDARY||request.query.boundary!=PRECLINICAL_BOUNDARY||!request.query.raw_data_local||!request.query.aggregate_only||request.minimum_selected==0{return Err(RetrievalAssuranceError::Invalid("assurance boundary, locality, aggregate-only, or minimum selection is invalid".into()));} let synthesis=retrieval_support::infer(&request.query,feature_id,version).map_err(|e|RetrievalAssuranceError::Inference(e.to_string()))?; let mut gates=vec!["evidence-state-qualified".into(),"replay-identity-matched".into(),"provenance-digests-present".into(),"raw-data-local".into()]; let mut omissions=Vec::new(); let mut uncertainty=Vec::new(); let mut negative=synthesis.negative_evidence_order.clone(); if synthesis.selected_order.len()<request.minimum_selected{gates.push("minimum-selected-failed".into());omissions.push("assurance:minimum-selected-not-met".into());} if require_approval&&!request.signed_approval{gates.push("signed-approval-missing".into());omissions.push("assurance:signed-approval-missing".into());} if require_federation&&!request.federation_approved{gates.push("federation-approval-missing".into());omissions.push("assurance:federation-approval-missing".into());} if synthesis.disposition!="qualified"{gates.push("synthesis-not-qualified".into());uncertainty.push("underlying synthesis remains partial, unknown, or blocked".into());} gates.sort();gates.dedup();omissions.extend(synthesis.omission_order.clone());omissions.sort();omissions.dedup();uncertainty.extend(synthesis.uncertainty_order.clone());uncertainty.sort();uncertainty.dedup();negative.sort();negative.dedup(); let safe=synthesis.disposition=="qualified"&&synthesis.selected_order.len()>=request.minimum_selected&&(!require_approval||request.signed_approval)&&(!require_federation||request.federation_approved); let disposition=if safe{"qualified"}else{"blocked"}; let effect_receipts=vec![if safe{"retain:qualified-retrieval-assurance"}else{"block:unsafe-release"}.into()]; let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":request.query.request_id,"disposition":disposition,"candidate_order":synthesis.candidate_order,"selected_order":synthesis.selected_order,"unresolved_order":synthesis.unresolved_order,"blocked_order":synthesis.blocked_order,"gate_order":gates,"omissions":omissions,"uncertainty":uncertainty,"negative_evidence":negative,"replay_identity":request.query.replay_identity,"synthesis_digest":synthesis.synthesis_digest,"effect_receipts":effect_receipts,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY}); let assurance_digest=ContentHash::of_value(&payload).map_err(|e|RetrievalAssuranceError::Artifact(e.to_string()))?; let artifact=TypedResearchArtifact::from_payload(format!("retrieval-assurance:{}",request.query.request_id),CONTENT_TYPE,&payload,vec![],vec![]).map_err(|e|RetrievalAssuranceError::Artifact(e.to_string()))?; let receipt=RetrievalAssuranceReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:request.query.request_id.clone(),disposition:disposition.into(),candidate_order:synthesis.candidate_order.clone(),selected_order:synthesis.selected_order.clone(),unresolved_order:synthesis.unresolved_order.clone(),blocked_order:synthesis.blocked_order.clone(),gate_order:gates,omissions,uncertainty,negative_evidence:negative,replay_identity:request.query.replay_identity.clone(),synthesis_digest:synthesis.synthesis_digest,assurance_digest,artifact,effect_receipts,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()}; receipt.validate()?;Ok(receipt)}
#[cfg(test)] mod tests { use super::*; use crate::retrieval_support::{RetrievalCandidate,RetrievalQuery}; fn h(s:&str)->ContentHash{ContentHash::of_bytes(s.as_bytes())} fn req()->RetrievalAssuranceRequest{let c=RetrievalCandidate{candidate_id:"candidate:assure".into(),source_id:"source:assure".into(),title:"assurance study".into(),study_id:"study:assure".into(),modality:"imaging".into(),relevance_milli:900,freshness_milli:900,evidence_state:"supported".into(),content_digest:h("content"),provenance_digest:h("provenance"),replay_identity:h("replay"),estimated_units:1,permitted:true,comparable:true,negative_result:false};RetrievalAssuranceRequest{query:RetrievalQuery{request_id:"assure:req".into(),researcher:"researcher".into(),corpus_id:"corpus".into(),purpose:"assure retrieval".into(),semantic_profile:"prov-v1".into(),query_terms:vec!["assure".into()],candidates:vec![c],minimum_relevance_milli:500,minimum_freshness_milli:500,max_budget_units:4,replay_identity:h("replay"),policy_allow:true,protected_closure:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()},minimum_selected:1,require_signed_approval:false,signed_approval:false,require_federation:false,federation_approved:false,boundary:PRECLINICAL_BOUNDARY.into()}} #[test]fn qualified_release_is_retained(){let r=assure(&req(),"AFA-worldgen-P02-F25","worldgen-local-retrieval-synthesis-assurance/1.0",false,false).unwrap();assert_eq!(r.disposition,"qualified");} #[test]fn minimum_gate_blocks(){let mut r=req();r.minimum_selected=2;let out=assure(&r,"AFA-worldgen-P02-F25","worldgen-local-retrieval-synthesis-assurance/1.0",false,false).unwrap();assert_eq!(out.disposition,"blocked");} #[test]fn approval_gate_blocks(){let mut r=req();r.require_signed_approval=true;let out=assure(&r,"AFA-worldgen-P02-F26","worldgen-multimodal-retrieval-synthesis-assurance/1.0",true,false).unwrap();assert_eq!(out.disposition,"blocked");} #[test]fn federation_gate_blocks(){let mut r=req();r.require_federation=true;let out=assure(&r,"AFA-worldgen-P02-F28","worldgen-federated-continual-retrieval-synthesis-assurance/1.0",true,true).unwrap();assert_eq!(out.disposition,"blocked");}}
